function overviewSummary(ctx,pending,waiting){
 const requests=pending.filter(id=>APPROVALS[id]?.amount),names={sai:'Sai Krupa PG',shivalik:'Shivalik',finch:'Finch',glow:'Glow'},labels=pending.includes('label')?(ctx.state.labelPending||[]).length:0;
 const reviewParts=[pending.includes('intro')?'27 introductions':'',labels?`${labels} buyer ${labels===1?'label':'labels'}`:''].filter(Boolean),compactParts=[pending.includes('intro')?'27 intros':'',labels?`${labels} buyer ${labels===1?'label':'labels'}`:''].filter(Boolean);
 const joinNames=items=>items.length<2?items[0]||'':`${items.slice(0,-1).join(', ')} and ${items.at(-1)}`;
 const buyerNames=requests.map(id=>names[id]||APPROVALS[id].title),requestCount=requests.length;
 let headline,compactHeadline,detail,compactDetail,next,compactNext;
 if(requestCount){
  headline=`${requestCount} ${requestCount===1?'buyer needs':'buyers need'} your approval · ${money(waiting)} in valid drafts`;
  compactHeadline=`${requestCount} ${requestCount===1?'approval':'approvals'} · ${money(waiting)} in valid drafts`;
  detail=`${joinNames(buyerNames)} ${requestCount===1?'is':'are'} waiting.`;
  compactDetail=buyerNames.join(', ');
  next=reviewParts.length?`Also review ${reviewParts.join(' and ')}.`:'All introductions and buyer labels are reviewed.';
  compactNext=compactParts.length?`${compactParts.join(' · ')} to review`:'Introductions and labels reviewed';
 }else if(pending.length){
  headline='Your buyer approvals are all done.';
  compactHeadline='Buyer approvals are all done';
  detail=`Review ${reviewParts.join(' and ')}.`;
  compactDetail=`${compactParts.join(' · ')} to review`;
  next='44 new business buyers found this week.';
  compactNext='44 new business buyers this week';
 }else{
  headline='You’re all caught up.';
  detail='All buyer requests have been reviewed.';
  next='Ray is tracking your next business opportunity.';
 }
 const line=(full,compact,strong=false)=>`<p class="overview-summary-line ${strong?'summary-headline':''}"><span class="summary-full">${esc(full)}</span><span class="summary-compact">${esc(compact||full)}</span></p>`;
 return `<section class="callout agent-recommendation overview-summary" aria-label="Your business summary">${icon(pending.length?'sparkles':'check-circle',20)}<div class="overview-summary-copy">${line(headline,compactHeadline,true)}${line(detail,compactDetail)}${line(next,compactNext)}</div>${button(pending.length?`Review ${pending.length}`:'See activity','overview-review','primary')}</section>`;
}

function renderOverview(ctx){
 const d=dstate(ctx),pending=ctx.state.pending||[],waiting=queueAmount(ctx.state);
 const range=ctx.state.range||'since',stats=performance(range);
 const vals=[{icon:'rupee',value:money(stats.revenue),label:'Revenue from identified businesses',sub:`${stats.orders} orders · ${stats.label.toLowerCase()}`,tone:'green'},{icon:'users',value:String(stats.accounts),label:'Business accounts',sub:`${stats.repeat} have reordered in this period`,tone:'blue'},{icon:'shopping-cart',value:money(stats.average),label:'Average business order',sub:'Based on orders in this period',tone:'purple'},{icon:'hourglass',value:String(pending.length),label:'Review items',sub:pending.length?`${money(waiting)} in valid order drafts`:'All caught up',tone:'amber',action:'overview-review'}];
 const funnel=stats.funnel;
 return `<div class="stack dashboard-overview"><div class="dashboard-kpis">${vals.map(k=>`<${k.action?'button':'div'} ${k.action?'data-action="overview-review"':''} class="dashboard-kpi ${k.action?'clickable':''}"><div class="kpi-icon ${k.tone}">${icon(k.icon,19)}</div><div class="kpi-value">${esc(k.value)}</div><div class="kpi-label">${esc(k.label)}</div><div class="muted small">${esc(k.sub)}</div></${k.action?'button':'div'}>`).join('')}</div>
 ${overviewSummary(ctx,pending,waiting)}
 <div class="overview-charts"><div class="card stack"><div class="section-head"><h3>Revenue from identified businesses</h3><span class="muted small">${range==='week'?'Daily':'Weekly'} · ${stats.label}</span></div><p class="muted small">${stats.caption}</p>${revenueChart(stats)}<div class="mobile-chart">${stats.buckets.map(b=>`<div><span>${b.label}</span><strong>${b.future?'Upcoming':money(b.amount)}</strong><i style="width:${b.amount/Math.max(1,...stats.buckets.map(b=>b.amount))*100}%"></i></div>`).join('')}</div><details class="chart-data"><summary>View chart data</summary><table class="data-table"><thead><tr><th>Period</th><th>Revenue</th></tr></thead><tbody>${stats.buckets.map(b=>`<tr><td>${b.label}</td><td>${b.future?'Upcoming':money(b.amount)}</td></tr>`).join('')}</tbody></table></details></div><div class="card stack"><h3>From found to ordering</h3><span class="muted small">${stats.caption}</span><div class="funnel-list">${funnel.map(([label,n],i)=>`<div><div class="row"><span>${esc(label)}</span><strong>${n.toLocaleString('en-IN')}</strong></div><div class="funnel-track"><span style="width:${n/Math.max(1,funnel[0][1])*100}%;background:${i>=4?'#20a06f':'#2b6ded'}"></span></div></div>`).join('')}</div></div></div>
 <div class="card stack"><div class="section-head"><h3 class="row">${icon('sparkles',18)} What I learned</h3><span class="muted small">Precision 78% → 86% after ${ctx.state.labelsCount||120} labels</span></div><div>${[...(ctx.state.extraLearned||[]).map(l=>({...l,isNew:true})),...LEARNED].map(l=>{const mark=d.learnedMarks[l.id]||ctx.state.learnedMarks?.[l.id];return `<div class="learned-row ${mark==='undone'?'undone':''}">${l.isNew?badge('New','success'):''}<span>${esc(l.text)}</span>${mark?badge(mark==='kept'?'Kept':'Undone',mark==='kept'?'success':'neutral'):`<div class="row">${actButton('Keep','learn-keep',l.id,'secondary')}${actButton('Undo','learn-undo',l.id,'ghost')}</div>`}</div>`;}).join('')}</div></div></div>`;
}
function revenueChart(stats){
 const max=Math.max(1,...stats.buckets.map(b=>b.amount)),points=stats.buckets.map((b,i)=>({...b,x:60+i*(470/Math.max(1,stats.buckets.length-1)),y:175-b.amount/max*125})),path=points.filter(p=>!p.future).map((p,i)=>`${i?'L':'M'}${p.x},${p.y}`).join(' ');
 return `<svg class="revenue-chart" viewBox="0 0 580 245" role="img" aria-label="${esc(stats.label)} revenue: ${money(stats.revenue)}. ${esc(stats.caption)}">${[0,.5,1].map(v=>`<line x1="55" x2="555" y1="${175-v*125}" y2="${175-v*125}" stroke="#e9eef5"/><text x="48" y="${179-v*125}" text-anchor="end" class="chart-axis">${v?money(Math.round(max*v/1000))+'k':'₹0'}</text>`).join('')}<path d="${path}" fill="none" stroke="#2b6ded" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" pathLength="1" class="chart-line"/>${points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4" fill="${p.future?'#d4dce7':'#fff'}" stroke="${p.future?'#d4dce7':'#2b6ded'}"/><text x="${p.x}" y="${p.y-12}" text-anchor="middle" class="chart-value">${p.future?'—':money(Math.round(p.amount/1000))+'k'}</text><text x="${p.x}" y="205" text-anchor="middle" class="chart-axis" transform="rotate(-25 ${p.x} 205)">${p.label}</text>`).join('')}</svg>`;
}
function evidenceChips(items){return `<div class="evidence-chips">${items.map(t=>`<span class="evidence-chip" title="${esc('Evidence from order history: '+t)}">${esc(t)}</span>`).join('')}</div>`;}
function quoteTable(rows,subtotal,tax,total){return `<div class="table-wrap"><table class="data-table quote-table"><thead><tr><th>Item</th><th class="right">Qty</th><th class="right">Rate</th><th class="right">Amount</th></tr></thead><tbody>${rows.map(([name,qty,rate,sum])=>`<tr><td>${esc(name)}</td><td class="right">${qty}</td><td class="right">${money(rate)}</td><td class="right">${money(sum)}</td></tr>`).join('')}</tbody></table><div class="quote-totals"><div><span>Subtotal, before GST</span><span>${money(subtotal)}</span></div><div><span>IGST 5%</span><span>${money(tax)}</span></div><div class="quote-total"><strong>Total</strong><strong>${money(total)}</strong></div></div></div>`;}
function messagePreview(id,ctx){return `<div class="stack gap-sm"><div class="section-head"><span class="eyebrow">MESSAGE PREVIEW</span>${actButton('Edit message','approval-edit',id,'ghost')}</div><div class="whatsapp-preview"><div class="message-bubble">${esc(dstate(ctx).messages[id]||INTRO_MESSAGE)}</div></div></div>`;}
function approvalHeader(id,title,sub,amount=0){return `<div class="stack gap-sm"><div>${badge(APPROVALS[id].type,tone(APPROVALS[id].tone))}</div><div class="section-head"><h2>${esc(title)}</h2>${amount?`<strong class="approval-amount">${money(amount)}</strong>`:''}</div><p class="muted">${esc(sub)}</p></div>`;}
function needsYou(body){return `<div class="callout neutral-callout">${icon('hand',17)}<div><strong>Why it needs you:</strong> ${body}</div></div>`;}
function approvalActions(id,main='Approve & send',extras=''){return `<div class="approval-actions row">${actButton(main,'approval-approve',id,'primary')}${extras}${actButton('Reject','approval-reject',id,'ghost')}<span class="flex-spacer"></span>${id!=='intro'?actButton('Reply myself','approval-reply',id,'ghost'):''}</div>`;}
function renderApprovalDetail(id,ctx){const d=dstate(ctx);
 if(id==='intro'){const selected=selectedRecipients(ctx.state);return `${approvalHeader(id,'Introduce new business buyers','27 opted-in buyers · choose recipients before scheduling')}${needsYou('review-first requires approval before messages are sent.')}${callout('Schedule for Tue 13 Oct at 10:00. Eight buyers without WhatsApp consent are excluded.')}<div class="row between"><strong>${selected.length} of 27 selected</strong>${button('Select all','intro-select-all','ghost')}${button('Clear selection','intro-clear','ghost')}</div><details class="intro-recipients" ${d.introExpanded?'open':''}><summary>Review all 27 recipients</summary><div class="intro-recipient-list">${INTRO_RECIPIENTS.map(b=>`<label class="intro-recipient"><input type="checkbox" data-action="intro-recipient" data-id="${b.id}" ${selected.some(x=>x.id===b.id)?'checked':''} ${b.confidence<Number(config(ctx).confidence)?'disabled':''}><div><strong>${esc(b.name)}</strong><span>${esc(b.city)} · ${b.confidence}% confidence</span><small>${esc(b.evidence)} · ${b.confidence<Number(config(ctx).confidence)?'Below your current confidence threshold':'WhatsApp opted in'}</small></div></label>`).join('')}</div></details><details class="secondary-details"><summary>Message preview</summary>${messagePreview(id,ctx)}</details>${approvalActions(id,`Schedule ${selected.length} selected`)}`;}
 if(id==='sai')return `${approvalHeader(id,'Sai Krupa PG','PG · Madhapur, Hyderabad · drafted today 08:50',21042)}${needsYou(config(ctx).quoteLimit===15000?'above your ₹15,000 approval threshold.':'drafted above the ₹15,000 approval threshold in effect when this quote was prepared.')}${callout('Approve as drafted. Both items qualify for Tier 2, stock is available, and the GSTIN is active.')}${evidenceChips(['4 orders in 6 weeks','22 single bedsheets','“PG” in shipping name','One UPI ID across orders'])}${quoteTable([['Single bedsheet · Tier 2',40,376,15040],['Pillow cover · Tier 2',40,125,5000]],20040,1002,21042)}<div class="row callout neutral-callout">${icon('plane',17)}<span>50% advance <strong>₹10,521</strong> by Payment Link · balance on delivery</span>${badge('Stock check passed','success')}</div><details class="secondary-details"><summary>Invoice and message previews</summary><div class="stack gap-sm"><span class="eyebrow">GST INVOICE PREVIEW</span><div class="invoice-preview"><div class="section-head"><strong>TAX INVOICE</strong>${badge('Draft · not issued')}<span class="muted small">INV/26-27/—</span></div><div class="grid-2"><div><span class="eyebrow">FROM</span><strong>Kesar Linen Co.</strong><span>Panipat, Haryana</span><span class="small">GSTIN 06AA•••••1Z4</span></div><div><span class="eyebrow">BILL TO</span><strong>Sai Krupa PG</strong><span>Madhapur, Hyderabad, Telangana</span><span class="small">GSTIN 36AB•••••1Z5</span></div></div><div class="invoice-meta">Place of supply Telangana (36) · HSN 6302 · IGST 5%</div></div></div>${messagePreview(id,ctx)}</details>${approvalActions(id)}`;
 if(id==='shivalik')return `${approvalHeader(id,'Hotel Shivalik Residency','Hotel · Dehradun · 60 bath towels + 30 bedsheets',32193)}${needsYou('they asked for 20% off, below your 15% discount floor.')}<div class="price-options"><div class="price-option"><span class="eyebrow">AT YOUR TIERS</span><strong>₹32,193</strong><span>Gross margin 41.9%</span><small>60 towels × ₹323 + 30 bedsheets × ₹376 + IGST 5%</small></div><div class="price-option caution"><span class="eyebrow">AT 20% OFF</span><strong>₹29,925</strong><span>Gross margin 37.5%</span><small>₹2,268 less than your tiers</small></div><div class="price-option recommended"><span class="eyebrow">RECOMMENDED</span><strong>₹39,406</strong><span>50 bedsheets unlock Tier 3</span><small>60 towels × ₹323 + 50 bedsheets × ₹363 + IGST 5%</small></div></div>${callout('Keep your tiers. Offer the 50+ price on bedsheets if they take 50: a bigger order, better pricing, and nothing below your floor.')}<div class="approval-actions row">${actButton('Approve recommendation','approval-approve',id,'primary')}${actButton('Allow 20% once','shivalik-exception',id)}${actButton('Decline','approval-reject',id,'ghost')}${actButton('Reply myself','approval-reply',id,'ghost')}</div>`;
 if(id==='finch'){const q=ctx.state.quotes?.finch||defaultQuote(),errors=quoteErrors(q),emb=Number(q.embroidery),valid=!errors.embroidery,sub=7315+35*emb,tax=Math.round(sub*.05);return `${approvalHeader(id,'Finch Analytics','Office · Pune · Diwali gifting for the team',quoteAmount(ctx.state,id)||0)}${needsYou('logo embroidery needs your confirmed price and delivery date.')}${valid?quoteTable([['Cushion cover · Tier 2',35,209,7315],['Logo embroidery · your price',35,emb,35*emb]],sub,tax,sub+tax):'<div class="callout warning">Enter a valid embroidery price to calculate this quote.</div>'}<div class="grid-2"><label class="field"><span>Embroidery per piece (₹)</span><input type="number" min="0" max="10000" step="1" data-action="finch-embroidery" value="${esc(q.embroidery)}" aria-invalid="${!!errors.embroidery}" aria-describedby="finch-price-error"><small id="finch-price-error" class="field-error">${errors.embroidery||''}</small></label><label class="field"><span>Delivery by</span><input type="date" min="2026-10-13" max="2027-10-12" data-action="finch-date" value="${esc(q.delivery)}" aria-invalid="${!!errors.delivery}" aria-describedby="finch-date-error"><small id="finch-date-error" class="field-error">${errors.delivery||'Buyer asked for 24 Oct'}</small></label></div>${callout('Suggested price ₹60 a piece. Confirm your embroiderer can meet the date before sending.')}<div class="approval-actions row">${actButton('Approve & send','approval-approve',id,'primary',Object.keys(errors).length?'disabled':'')}${actButton('Reject','approval-reject',id,'ghost')}${actButton('Reply myself','approval-reply',id,'ghost')}</div>`;}
 if(id==='glow')return `${approvalHeader(id,'Glow Unisex Salon','Account · Bengaluru · GSTIN verified · opening a second branch',27122)}${needsYou('they asked for 15 days’ credit. Direct credit is off in your rules.')}${quoteTable([['Hand towel · Tier 3',80,121,9680],['Bath towel · Tier 3',50,323,16150]],25830,1292,27122)}<div class="stack gap-sm">${[['financing','Offer Checkout Financing','A financing partner pays you upfront; the salon pays them in 15 days.'],['advance','Ask for the usual 50% advance','₹13,561 now by Payment Link, balance on delivery.'],['decline','Decline credit','Reply politely and keep the account warm.']].map(([v,t,s])=>`<label class="choice-card ${d.glowChoice===v?'selected':''}"><input type="radio" name="credit-choice" value="${v}" data-action="glow-choice" ${d.glowChoice===v?'checked':''}><div><strong>${esc(t)} ${v==='financing'?badge('Recommended','success'):''}</strong><p class="muted">${esc(s)}</p></div></label>`).join('')}</div>${approvalActions(id,'Approve choice')}`;
 if(id==='label')return `${approvalHeader(id,`${(ctx.state.labelPending||[]).length} low-confidence buyers to label`,'Below 0.80 confidence, so nobody has been contacted. Your answer improves detection.')}<div class="stack">${(ctx.state.labelPending||[]).map(id=>{const l=LABELS[id];return `<div class="card label-card"><div class="section-head"><div><strong>${esc(l.name)}</strong><span class="muted small"> · ${esc(l.city)}</span></div>${badge('Possible 0.'+l.conf)}</div><p>${esc(l.evidence)}</p><div class="row">${actButton('Business','buyer-label-business',id)}${actButton('Not a business','buyer-label-not',id)}${actButton('Not sure','buyer-label-unsure',id,'ghost')}</div></div>`;}).join('')}</div>`;
 return '';
}
function guardedDetail(id,ctx){let html=renderApprovalDetail(id,ctx);const rule=id==='intro'?'intro':id==='finch'?'custom':id==='glow'?'credit':id==='shivalik'?'floor':quoteAmount(ctx.state,id)>Number(ctx.state.config.quoteLimit)?'qhigh':'qlow';const reason=id==='intro'&&!selectedRecipients(ctx.state).length?'Select at least one eligible recipient':effectiveRule(ctx.state,rule)==='never'?'This action is disabled in your rules':ctx.state.paused?'Agent paused · resume to send':!connected(ctx.state,'whatsapp')?'WhatsApp disconnected · reconnect to send':'';if(reason){html=html.replace(/(<button[^>]*data-action="(?:approval-approve|shivalik-exception|intro-next)"[^>]*)>/g,'$1 disabled>');html=`<div class="callout warning" role="status">${esc(reason)}${ctx.state.paused?button('Resume agent','agent-resume','secondary'):!connected(ctx.state,'whatsapp')?actButton('Reconnect WhatsApp','connector-reconnect','whatsapp'):''}</div>`+html;}return html;}
function renderApprovals(ctx){const d=dstate(ctx),pending=ctx.state.pending||[];if(!pending.length)return `<div class="card approval-empty">${icon('check-circle',44)}<h2>You’re all caught up</h2><p class="muted">New approvals will appear here. Everything you reviewed is in Activity.</p>${button('See activity','overview-activity')}</div>`;const selected=pending.includes(d.approval)?d.approval:pending[0];d.approval=selected;return `<div class="approvals-layout"><div class="approval-list"><div class="section-head"><strong>${pending.length} review items</strong><span class="muted small">${pending.filter(id=>quoteAmount(ctx.state,id)!==0).length} quotes · ${pending.filter(id=>['intro','label'].includes(id)).length} batches</span></div><div class="approval-options">${pending.map(id=>{const a=APPROVALS[id];return `<button class="approval-card ${selected===id?'selected':''}" data-action="approval-select" data-id="${id}"><div class="section-head">${badge(a.type,tone(a.tone))}<strong>${id==='intro'?'27 buyers':quoteAmount(ctx.state,id)===null?'Needs price':quoteAmount(ctx.state,id)?money(quoteAmount(ctx.state,id)):''}</strong></div><strong>${id==='label'?`${(ctx.state.labelPending||[]).length} buyers to label`:esc(a.title)}</strong><span class="muted small">${esc(a.why)}</span></button>`;}).join('')}</div></div><div class="card approval-detail stack" key="${selected}">${guardedDetail(selected,ctx)}</div></div>`;}

function renderActivity(ctx){const d=dstate(ctx),all=events(ctx),filtered=all.filter(e=>(d.activityCat==='all'||e.cat===d.activityCat)&&(d.activityWho==='all'||(d.activityWho==='approved'?e.manual:!e.manual)));return `<div class="stack">${activityViewNav('activity')}${ctx.state.scheduledIntro?.status==='Scheduled'?`<div class="callout neutral-callout"><span><strong>${ctx.state.scheduledIntro.recipientIds.length} introductions scheduled</strong> · Tue 13 Oct, 10:00</span>${button('Cancel schedule','intro-cancel-schedule')}</div>`:''}<div class="activity-toolbar"><div class="filter-chips">${CATEGORIES.map(c=>actButton(titleCase(c),'activity-category',c,d.activityCat===c?'primary':'secondary')).join('')}</div><div class="row"><div class="segmented">${[['all','All'],['auto','Auto'],['approved','Approved']].map(([id,label])=>actButton(label,'activity-who',id,d.activityWho===id?'selected':'ghost')).join('')}</div>${button('Export CSV','activity-export')}</div></div>${filtered.length?['Today','Yesterday'].map(day=>{const list=filtered.filter(e=>(e.day||'Today')===day);return list.length?`<section class="activity-group"><div class="row activity-date"><span>${day} · ${day==='Today'?'12 Oct':'11 Oct'}</span><span class="muted">${list.length} actions</span></div>${list.map(e=>`<button class="activity-row ${e.isNew?'new-event':''}" data-action="activity-open" data-id="${esc(e.id)}"><span class="activity-dot ${eventTone(e)}">${icon(eventTone(e)==='error'?'shield':eventTone(e)==='warning'?'clock':'check',14)}</span><div><strong>${esc(e.title)}</strong><span> · ${esc(e.buyer)}${e.amount?` · ${amt(e.amount)}`:''}</span>${e.isNew?badge('New','info'):''}<div class="muted small">${esc(e.time||'Just now')} · ${esc(e.by||'Approved by Neha')}</div></div>${badge(e.status||'Done',eventTone(e))}${icon('chevron-right',16)}</button>`).join('')}</section>`:'';}).join(''):`<div class="card empty-state"><h3>Nothing matches these filters</h3><p class="muted">Every action the agent takes is logged with its reason.</p>${button('Clear filters','activity-clear')}</div>`}</div>`;}
function activityDrawer(e){const trace=e.trace||[];const total=trace.reduce((n,step)=>{const s=String(step[1]);const m=s.match(/(\d+)m\s*(\d+)s/);return n+(m?Number(m[1])*60+Number(m[2]):parseFloat(s)||0);},0);const id='run_'+String(e.id).replace(/[^a-z0-9]/gi,'').slice(0,10);return `<div class="overlay-head"><div><div class="row"><span class="mono small">${esc(id)}</span>${badge(e.status||'Done',eventTone(e))}</div><h2>${esc(e.title)}</h2><p class="muted">B2B Customer Agent · ${esc(e.buyer)}${e.amount?' · '+amt(e.amount):''}</p><span class="muted small">${esc(e.time||'Just now')} · ${esc(e.by||'Approved by Neha')}</span></div>${button('×','overlay-close','ghost','aria-label="Close activity details"')}</div><div class="overlay-body stack"><p>${esc(e.detail||'Action recorded in your audit trail.')}</p>${e.quote?`<blockquote>${esc(e.quote)}</blockquote>`:''}<div class="callout neutral-callout">${icon('info',17)}<div><strong>Why:</strong> ${esc(e.why||'You reviewed and approved this action.')}</div></div>${trace.length?`<div class="section-head"><h3>Run trace</h3><span class="muted mono small">${total>=60?Math.floor(total/60)+'m '+Math.round(total%60)+'s':total.toFixed(1)+'s'}</span></div><div class="trace-list">${trace.map(([name,duration,detail],i)=>`<div class="trace-step"><span class="trace-dot">${icon('check',13)}</span><div><strong>${esc(name)}</strong><p class="muted small">${esc(detail)}</p></div><span class="muted mono small">${esc(duration)}</span></div>`).join('')}</div>`:`<p class="muted small">Single-step action, so there’s no multi-step run trace.</p>`}</div><div class="overlay-footer muted small">Every step the agent takes is logged with its reason.</div>`;}

function renderBuyers(ctx){const d=dstate(ctx),all=buyers(ctx),q=d.buyerSearch.trim().toLowerCase();const rows=all.filter(b=>(d.buyerGroup==='all'||b.groups?.includes(d.buyerGroup))&&(d.buyerType==='all'||b.type===d.buyerType)&&(!q||(b.name+' '+b.city).toLowerCase().includes(q)));return `<div class="stack">${activityViewNav('buyers')}<div class="buyers-toolbar"><label class="search-field">${icon('search',17)}<input aria-label="Search buyers or cities" data-action="buyers-search" value="${esc(d.buyerSearch)}" placeholder="Search buyers or cities"></label><select aria-label="Filter by business type" data-action="buyers-type"><option value="all">All types</option>${[['pg','PGs and hostels'],['hotel','Hotels and homestays'],['salon','Salons and spas'],['office','Offices and gifting'],['cafe','Cafés and restaurants'],['other','Other']].map(([id,l])=>`<option value="${id}" ${d.buyerType===id?'selected':''}>${esc(l)}</option>`).join('')}</select><span class="muted small">${rows.length} of ${all.length} shown · 1,352 detected in total</span></div><div class="filter-chips">${GROUPS.map(([id,label])=>actButton(`${label} <span class="chip-count">${id==='all'?all.length:all.filter(b=>b.groups?.includes(id)).length}</span>`,'buyers-group',id,d.buyerGroup===id?'primary':'secondary')).join('')}</div><div class="mobile-buyer-list">${rows.map(b=>`<button class="mobile-buyer" data-action="buyer-open" data-id="${b.id}"><div class="row between"><strong>${esc(b.name)}</strong>${icon('chevron-right',16)}</div><span>${esc(b.typeLabel)} · ${esc(b.city)}</span><div class="row between">${badge(b.status,b.tone)}<strong>${money(b.spend)}</strong></div><small>Spend · 6 months · updated ${esc(b.last)}</small></button>`).join('')}</div><div class="table-wrap buyers-table"><table class="data-table"><thead><tr><th>Buyer</th><th>City</th><th>Detection</th><th>Evidence</th><th>Status</th><th class="right">Spend · 6 mo</th><th>Last activity</th></tr></thead><tbody>${rows.map(b=>`<tr data-action="buyer-open" data-id="${b.id}" tabindex="0" role="button" aria-label="View ${esc(b.name)}"><td><div class="row"><span class="buyer-avatar">${esc(b.name.replace(/[^A-Za-z]/g,'').slice(0,2).toUpperCase())}</span><div><strong>${esc(b.name)}</strong><div class="muted small">${esc(b.typeLabel)}</div></div></div></td><td>${esc(b.city)}</td><td>${badge(b.detection,b.detection.startsWith('Likely')?'success':'neutral')}</td><td>${b.evidence.length?evidenceChips(b.evidence):'<span class="muted">—</span>'}</td><td>${badge(b.status,b.tone)}</td><td class="right nowrap">${money(b.spend)}</td><td class="muted nowrap small">${esc(b.last)}</td></tr>`).join('')}</tbody></table>${!rows.length?`<div class="empty-state"><h3>No buyers here right now</h3><p class="muted">Try another filter, or clear your search.</p>${button('Show all buyers','buyers-clear')}</div>`:''}</div></div>`;}
function buyerNext(b,ctx){const o=ctx.state.buyerOverrides?.[b.id];if(!o)return b.next;if(/excluded|opted out/i.test(o.status))return 'This buyer is excluded from agent outreach. No new messages or calls will be sent.';if(/paused/i.test(o.status))return 'Outreach is paused for this buyer. Resume outreach when you are ready.';if(/not a business/i.test(o.status))return 'Removed from business outreach. Your label will improve similar detections.';if(/intro queued/i.test(o.status))return 'Confirmed by you and added to the next intro queue, inside consent and quiet-hour rules.';if(/rejected|declined/i.test(o.status))return 'Your decision is recorded. The agent will keep this account available for future orders.';if(b.id==='sai')return 'The quote is sent. Waiting for the ₹10,521 advance before dispatch.';if(b.id==='shivalik')return 'Your offer has been sent. The agent is waiting for the buyer’s response.';if(b.id==='finch')return `${money(o.quoteAmount||quoteAmount(ctx.state,'finch'))} custom quote sent with delivery ${ctx.state.quotes?.finch?.delivery}. Waiting for confirmation.`;if(b.id==='glow')return 'Your selected payment option has been shared. The agent is waiting for the salon’s response.';return o.status||b.next;}
function buyerDrawer(b,ctx){const changed=ctx.state.buyerOverrides?.[b.id],chat=dstate(ctx).replies?.[b.id]||[];const convo=b.id==='sai'?[['out',INTRO_MESSAGE,'Tue 6 Oct 10:00'],['in','Yes, I run a 40-bed PG, need GST bill','11:14'],['out','Please share your GSTIN and I’ll put the invoice in your firm’s name.','11:14'],['in','GSTIN 36AB•••••1Z5','12:02'],['sys','GSTIN verified · Sai Krupa PG, Telangana',''],['in','Need 40 bedsheets and 40 pillow covers','Fri 9 Oct 19:20'],['sys',changed?b.status:'Quote drafted · waiting for your approval',''],...chat.map(t=>['out',t,'Just now'])]:chat.map(t=>['out',t,'Just now']);return `<div class="overlay-head"><div><div class="row"><span class="buyer-avatar large">${esc(b.name.replace(/[^A-Za-z]/g,'').slice(0,2).toUpperCase())}</span><div><h2>${esc(b.name)}</h2><p class="muted">${esc(b.typeLabel)} · ${esc(b.city)}</p></div></div><div class="row">${badge(b.status,b.tone)}${badge(b.detection,'neutral')}</div></div>${button('×','overlay-close','ghost','aria-label="Close buyer details"')}</div><div class="overlay-body stack">${b.why?.length?section('Why I think this is a business',`<div class="stack gap-sm">${b.why.map(([t,s])=>`<div class="row evidence-reason">${icon('check-circle',17)}<div><strong>${esc(t)}</strong><p class="muted small">${esc(s)}</p></div></div>`).join('')}</div>`):''}${b.orders?section('Orders',`<div>${b.orders.map(([date,items,amount])=>`<div class="order-row"><span class="muted small">${esc(date)}</span><span>${esc(items)}</span><strong>${money(amount)}</strong></div>`).join('')}</div><p class="callout neutral-callout small">${esc(b.payer)}</p>`):''}<section class="stack gap-sm"><h3>Details</h3><dl class="buyer-details"><dt>Consent</dt><dd>${esc(b.consent)}</dd><dt>Risk signals</dt><dd>${badge('Low','success')}</dd><dt>GSTIN</dt><dd class="mono small">${esc(b.gstin)}</dd><dt>Spend · 6 months</dt><dd>${money(b.spend)}</dd><dt>Current quote</dt><dd>${b.quoteAmount?money(b.quoteAmount):(ctx.state.pending||[]).includes(b.id)?quoteAmount(ctx.state,b.id)===null?'Needs a valid price':money(quoteAmount(ctx.state,b.id)):'—'}</dd><dt>Last activity</dt><dd>${esc(b.last)}</dd></dl></section>${convo.length?section('Conversation · WhatsApp',`<div class="whatsapp-preview conversation">${convo.map(([who,text,time])=>who==='sys'?`<div class="system-message">${esc(text)}</div>`:`<div class="message-bubble ${who==='in'?'incoming':''}">${esc(text)}<small>${esc(time)}</small></div>`).join('')}</div>`):''}<div class="callout neutral-callout">${icon('arrow-right',19)}<div><strong>Next step</strong><p>${esc(buyerNext(b,ctx))}</p>${(ctx.state.pending||[]).includes(b.id)?actButton('Review in approvals','buyer-review',b.id,'ghost'):''}</div></div></div><div class="overlay-footer buyer-actions">${actButton('Confirm business','buyer-label-business',b.id,'primary')}${actButton('Not a business','buyer-label-not',b.id)}${actButton(/paused/i.test(b.status)?'Resume outreach':'Pause outreach',/paused/i.test(b.status)?'buyer-resume':'buyer-label-pause',b.id)}${actButton('Exclude','buyer-exclude-confirm',b.id,'ghost')}</div>`;}

function settingsInput(label,key,value,type='number',extra=''){return `<label class="field"><span>${esc(label)}</span><input type="${type}" data-action="settings-input" data-key="${key}" value="${esc(String(value))}" ${extra}></label>`;}
function renderSettings(ctx){const d=dstate(ctx),c=d.settingsDraft||config(ctx),dirty=!!d.settingsDraft;return `<div class="settings-layout"><nav class="settings-nav">${[['mode','Mode'],['pricing','Pricing & outreach'],['notifications','Notifications'],['connectors','Connectors'],['danger','Danger zone']].map(([id,l])=>actButton(l,'settings-jump',id,'ghost')).join('')}</nav><div class="stack settings-body"><section id="settings-mode" class="stack"><div><h2>Mode</h2><p class="muted">Review-first requires approval for every outgoing action. In automatic mode, each action follows the rules below.</p></div><div class="grid-2" role="radiogroup" aria-label="Operating mode">${[['review','Review-first','You approve every outgoing action.'],['auto','Auto within your rules','Exceptions still come to you. Available after 14 days of review-first.']].map(([id,t,s])=>`<button class="choice-card ${c.mode===id?'selected':''}" data-action="settings-mode" data-id="${id}" role="radio" aria-checked="${c.mode===id}" tabindex="${c.mode===id?0:-1}" ${id==='auto'&&!autoAvailable(ctx.state)?'disabled':''}><span class="mode-radio" aria-hidden="true"></span><div><strong>${t}</strong><p class="muted">${s}</p></div></button>`).join('')}</div><div class="table-wrap"><table class="data-table autonomy-table"><thead><tr><th>Action</th><th>Auto</th><th>Ask me</th><th>Never</th></tr></thead><tbody>${AUTONOMY.map(([id,l,v,locked])=>`<tr role="radiogroup" aria-label="${esc(l)}"><td>${esc(l)} ${locked?badge('Never auto'):''}</td>${['auto','ask','never'].map(mode=>`<td><button class="radio-control ${c.autonomy[id]===mode?'checked':''}" data-action="settings-autonomy" data-id="${id}" data-value="${mode}" ${(locked||c.mode==='review')&&mode==='auto'?'disabled':''} aria-label="${esc(l+': '+mode)}" role="radio" aria-checked="${c.autonomy[id]===mode}" tabindex="${c.autonomy[id]===mode?0:-1}"><span></span></button></td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section id="settings-pricing" class="stack"><div><h2>Pricing and outreach</h2><p class="muted">The agent stays inside your price floor, order minimum and outreach limits.</p></div><div class="grid-3">${c.tiers.map((v,i)=>`<div class="card tier-setting"><span>${['10–24 pieces','25–49 pieces','50+ pieces'][i]} ${i===2?badge('Floor'):''}</span>${settingsInput('Discount (%)','tier-'+i,v,'number','min="1" max="59"')}</div>`).join('')}</div><div class="grid-2">${settingsInput('Automatic quote limit after unlock (₹)','quoteLimit',c.quoteLimit,'number','min="0" max="10000000"')}${settingsInput('Minimum order (pieces)','moq',c.moq,'number','min="1" max="1000"')}${settingsInput('Messages per buyer per week, at most','weeklyMessages',c.weeklyMessages,'number','min="0" max="20"')}${settingsInput('Follow-ups in total, at most','followups',c.followups,'number','min="0" max="10"')}${settingsInput('Quiet hours start (IST)','quietStart',c.quietStart,'time')}${settingsInput('Quiet hours end (IST)','quietEnd',c.quietEnd,'time')}</div><div><h3>Languages</h3><div class="filter-chips">${LANGUAGES.map(l=>actButton(l,'settings-language',l,c.languages.includes(l)?'primary':'secondary')).join('')}</div><p class="muted small">English and Hindi are enabled by default. Regional language calls use Sarvam AI.</p></div><div class="card stack"><div class="section-head"><strong>Contact buyers with confidence of</strong><span class="confidence">${(Number(c.confidence)/100).toFixed(2)} or more</span></div><input type="range" min="50" max="95" step="1" value="${c.confidence}" data-action="settings-confidence" aria-label="Minimum business confidence"><div class="section-head muted small"><span>More buyers, more misses</span><span>Precision today: 86%</span><span>Fewer, surer</span></div></div></section><section id="settings-notifications" class="stack"><h2>Notifications</h2><div class="card notification-list">${[['approvalWhatsapp','Approvals to my WhatsApp','+91 99XXX XX107 · approve or reject with one tap'],['weeklyBrief','Weekly brief','Every Monday at 9:00 · dashboard and WhatsApp']].map(([id,t,s])=>`<div class="section-head"><div><strong>${t}</strong><p class="muted small">${s}</p></div><button class="switch ${c[id]?'on':''}" data-action="settings-toggle" data-id="${id}" role="switch" aria-checked="${!!c[id]}" aria-label="${t}"><span></span></button></div>`).join('')}</div></section><section id="settings-connectors" class="stack"><h2>Connectors</h2>${connectorStatus(ctx.state,'tally').includes('Expires')?`<div class="callout warning-callout">${icon('warning',19)}<div><strong>Tally connection expires in 3 days.</strong><p>Invoice actions will wait until its demo connection is renewed.</p></div>${actButton('Reconnect','connector-reconnect','tally','primary')}</div>`:''}<div class="card connector-list">${CONNECTORS.map(([id,name,status])=>{const st=connectorStatus(ctx.state,id);return `<div class="section-head"><div class="row"><span class="connector-avatar">${esc(name.slice(0,2))}</span><strong>${name}</strong></div><div class="row">${badge(st,st.includes('Expires')?'warning':st==='Built in'?'neutral':st==='Disconnected'?'neutral':'success')}${actButton('Manage','connector-manage',id,'ghost')}</div></div>`;}).join('')}</div></section><section id="settings-danger" class="stack"><h2>Danger zone</h2><div class="card danger-card"><div class="section-head"><div><strong>${ctx.state.paused?'Resume':'Pause'} B2B Customer Agent</strong><p class="muted small">${ctx.state.paused?'It’s paused. No actions are going out.':'Stops messages, calls and quotes immediately. Nothing is deleted.'}</p></div>${button(ctx.state.paused?'Resume agent':'Pause agent','settings-pause')}</div><div class="section-head"><div><strong>Uninstall B2B Customer Agent</strong><p class="muted small">Removes its demo access. Your audit trail remains available.</p></div>${button('Uninstall','settings-uninstall','danger')}</div></div></section>${dirty?`<div class="settings-savebar"><span>${icon('edit',17)} You have unsaved changes to your rules.</span><div class="row">${button('Discard','settings-discard','ghost')}${button('Save changes','settings-save','primary')}</div></div>`:''}</div></div>`;}

export function renderDashboard(ctx,tab='overview'){const d=dstate(ctx);d.tab=tab;return ({overview:renderOverview,approvals:renderApprovals,activity:renderActivity,buyers:renderBuyers,settings:renderSettings,rules:renderSettings}[tab]||renderOverview)(ctx);}
function openBuyer(id,ctx){dstate(ctx).openBuyer=id;const b=buyers(ctx).find(b=>b.id===id);if(b)ctx.drawer(buyerDrawer(b,ctx));}
function persistSettingsDraft(ctx,patch){const d=dstate(ctx);d.settingsDraft={...(d.settingsDraft||config(ctx)),...patch};ctx.rerender();}
function resolveApproval(id,kind,ctx){const d=dstate(ctx),a=APPROVALS[id];if(!(ctx.state.pending||[]).includes(id))return;const rule=id==='intro'?'intro':id==='finch'?'custom':id==='glow'?'credit':id==='shivalik'?'floor':quoteAmount(ctx.state,id)>Number(ctx.state.config.quoteLimit)?'qhigh':'qlow';if(effectiveRule(ctx.state,rule)==='never'&&kind!=='rejected'){ctx.toast('This action is disabled in your rules. Change the rule before sending.');return;}if((ctx.state.paused||!connected(ctx.state,'whatsapp'))&&kind!=='rejected'){ctx.toast('Resume the agent and connect WhatsApp before sending. Your item stays in the queue.');return;}let entry,buyer,action=kind;
 if(kind==='rejected'){entry=logEntry(id==='intro'?'Intro batch rejected':'Request declined',id==='intro'?'27 new likely business buyers':a.title,id==='intro'?'messages':'quotes',id==='intro'?'No messages sent':'Your decision recorded; no quote sent',quoteAmount(ctx.state,id)||undefined,{by:'Rejected by Neha',why:'You rejected this drafted action.'});if(id!=='intro')buyer={id,status:'Request declined by you',tone:'neutral',groups:id==='glow'?['accounts']:['quoted']};}
 else if(id==='intro'){const recipients=selectedRecipients(ctx.state);if(!recipients.length){ctx.toast('Select at least one recipient.');return;}ctx.state.scheduledIntro={recipientIds:recipients.map(b=>b.id),status:'Scheduled',scheduledFor:'2026-10-13T10:00:00+05:30'};entry=logEntry('Intros scheduled',`${selectedRecipients(ctx.state).length} selected business buyers`,'messages','Scheduled for Tue 13 Oct at 10:00 · opted-in buyers only',undefined,{status:'Scheduled',message:d.messages.intro,why:'You approved the intro batch. Tuesday 10:00 gets the most replies from PG owners.'});action='approved';}
 else if(id==='sai'){entry=logEntry('Quote sent',a.title,'quotes','40 sheets + 40 pillow covers · Tier 2 · advance ₹10,521',21042,{message:d.messages.sai,trace:[['Approval received','0.1s','Approved by Neha'],['Validate GSTIN','0.7s','Active · Telangana'],['Reserve stock','0.8s','40 bedsheets + 40 pillow covers'],['Create quote','0.6s','₹20,040 + IGST ₹1,002'],['Create Payment Link','0.5s','50% advance ₹10,521'],['Send on WhatsApp','1.0s','Delivered to buyer']]});buyer={id,status:'Quote sent · advance pending',tone:'info',groups:['quoted']};}
 else if(id==='shivalik'){const exception=kind==='exception';entry=logEntry(exception?'20% discount approved once':'Counter-offer sent',a.title,exception?'guardrails':'quotes',exception?'One-time price below floor · ₹2,268 less than your tiers':'60 towels + 50 bedsheets at your tiers',exception?29925:39406,{why:exception?'You explicitly approved a one-time below-floor price. Your standard floor is unchanged.':'You approved the larger-order recommendation within your tiers.'});buyer={id,status:exception?'Quote sent · 20% off once':'Counter-offer sent',tone:'info',groups:['quoted']};}
 else if(id==='finch'){const q=ctx.state.quotes?.finch||defaultQuote(),errors=quoteErrors(q);if(Object.keys(errors).length){ctx.rerender();document.querySelector('[aria-invalid="true"]')?.focus();ctx.toast('Correct the highlighted fields before sending.');return;}const rate=Number(q.embroidery),total=quoteAmount(ctx.state,id);entry=logEntry('Custom quote sent',a.title,'quotes',`35 cushion covers + logo embroidery at ₹${rate} a piece · delivery by ${q.delivery}`,total);buyer={id,status:'Custom quote sent',tone:'info',groups:['quoted']};}
 else if(id==='glow'){const v=d.glowChoice||'financing',details={financing:['Checkout Financing offered','Financing partner pays you upfront; buyer pays in 15 days','Financing offered',27122],advance:['Advance requested','50% advance by Payment Link; balance on delivery','Advance requested',13561],decline:['Credit request declined','Polite reply sent; account stays available','Credit declined',27122]}[v];entry=logEntry(details[0],a.title,v==='financing'?'payments':'quotes',details[1],details[3]);buyer={id,status:details[2],tone:v==='decline'?'neutral':'info',groups:['accounts']};action=v;}
 ctx.resolve(id,action||'approved',entry,buyer);ctx.toast(id==='intro'&&kind!=='rejected'?`Intros scheduled for ${selectedRecipients(ctx.state).length} buyers · Tue 13 Oct, 10:00`:`${entry.title} · ${entry.buyer}`);d.approval=(ctx.state.pending||[]).find(p=>p!==id);ctx.closeOverlay();ctx.rerender();}
function approvalEdit(id,ctx){dstate(ctx).editing=id;ctx.modal(`<div class="overlay-head"><div><h2>Edit drafted message</h2><p class="muted">${id==='intro'?'Intro to opted-in business buyers':'Quote for Sai Krupa PG'}</p></div>${button('×','overlay-close','ghost','aria-label="Close editor"')}</div><div class="overlay-body stack"><label class="field"><span>WhatsApp message</span><textarea rows="7" data-action="approval-message" data-id="${id}">${esc(dstate(ctx).messages[id])}</textarea></label><p class="muted small">The draft is saved locally and used when you approve.</p></div><div class="overlay-footer row">${button('Cancel','overlay-close')}${actButton('Save draft','approval-save-message',id,'primary')}</div>`);}
function connectorManage(id,ctx){const c=config(ctx),item=CONNECTORS.find(x=>x[0]===id);if(!item)return;const status=connectorStatus(ctx.state,id),built=['payments','checkout'].includes(id);ctx.modal(`<div class="overlay-head"><div><h2>${item[1]} connection</h2><p class="muted">Synthetic connection for this prototype</p></div>${button('×','overlay-close','ghost','aria-label="Close connector settings"')}</div><div class="overlay-body stack"><div class="section-head"><strong>Status</strong>${badge(status,status==='Disconnected'?'neutral':status.includes('Expires')?'warning':'success')}</div><dl class="buyer-details"><dt>Account</dt><dd>Kesar Linen Co.</dd><dt>Access</dt><dd>${built?'Read payment and checkout events':id==='tally'?'Create GST invoice drafts':id==='shopify'?'Read catalogue, check stock and reserve orders':'Read delivery status and run approved actions'}</dd><dt>Last sync</dt><dd>Today, 11:45 IST</dd></dl><p class="callout neutral-callout small">Connection changes update the local demo. No external account is contacted.</p></div><div class="overlay-footer row">${built?button('Done','overlay-close','primary'):status==='Disconnected'?actButton('Connect demo','connector-reconnect',id,'primary'):`${actButton('Reconnect','connector-reconnect',id,'primary')}${actButton('Disconnect','connector-disconnect',id,'ghost')}`}</div>`);}
function validateConfig(c){const [a,b,t]=c.tiers.map(Number);if(!(a>0&&a<b&&b<t&&t<60))return 'Each tier must give a larger discount, between 1% and 59%.';if(!(Number.isFinite(c.quoteLimit)&&c.quoteLimit>=0&&Number.isInteger(c.moq)&&c.moq>=1&&c.moq<=1000))return 'Minimum order must be a whole number from 1 to 1,000; quote limit cannot be negative.';if(!(Number.isInteger(c.weeklyMessages)&&c.weeklyMessages>=0&&c.weeklyMessages<=20&&Number.isInteger(c.followups)&&c.followups>=0&&c.followups<=10))return 'Weekly messages must be a whole number from 0 to 20; follow-ups from 0 to 10.';if(!c.languages.length)return 'Select at least one language.';if(c.quietStart===c.quietEnd)return 'Quiet-hour start and end must be different.';return '';}

export function handleDashboard(action,el,ctx){const d=dstate(ctx),id=el?.dataset?.id;
 if(action==='overview-review'){ctx.nav((ctx.state.pending||[]).length?'approvals':'activity');return true;}
 if(action==='overview-activity'){ctx.nav('activity');return true;}
 if(action==='learn-keep'||action==='learn-undo'){const mark=action==='learn-keep'?'kept':'undone';d.learnedMarks[id]=mark;ctx.update({learnedMarks:{...(ctx.state.learnedMarks||{}),[id]:mark}});ctx.toast(mark==='kept'?'Kept · this stays in how I decide':'Undone · returned to the previous behaviour');return true;}
 if(action==='approval-select'){d.approval=id;ctx.rerender();document.querySelector('.approval-detail')?.scrollTo(0,0);if(globalThis.matchMedia?.('(max-width:600px)').matches)document.querySelector('.approval-detail')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});return true;}
 if(action==='approval-edit'){approvalEdit(id,ctx);return true;}
 if(action==='approval-message'){d.messageDraft=el.value;return true;}
 if(action==='approval-save-message'){const t=document.querySelector('[data-action="approval-message"]');const text=t?t.value:d.messageDraft;if(!text?.trim()){ctx.toast('Add a message before saving.');return true;}d.messages[id]=text.trim();ctx.update({approvalDrafts:{...(ctx.state.approvalDrafts||{}),[id]:text.trim()}});ctx.closeOverlay();ctx.rerender();ctx.toast('Message draft updated');return true;}
 if(action==='approval-approve'){resolveApproval(id,'approved',ctx);return true;}
 if(action==='shivalik-exception'){ctx.modal(`<div class="overlay-head"><h2>Allow 20% off for this order?</h2></div><div class="overlay-body stack"><p>Hotel Shivalik · ₹29,925 total · 37.5% gross margin.</p><p>This is ₹2,268 below your standard tiers. The 15% floor remains unchanged for future orders.</p></div><div class="overlay-footer row">${button('Cancel','overlay-close')}${actButton('Confirm one-time exception','shivalik-exception-confirm',id,'primary')}</div>`);return true;}
 if(action==='shivalik-exception-confirm'){resolveApproval(id,'exception',ctx);return true;}
 if(action==='approval-reject'){ctx.modal(`<div class="overlay-head"><h2>${id==='intro'?'Reject intro batch?':'Decline this request?'}</h2>${button('×','overlay-close','ghost','aria-label="Close confirmation"')}</div><div class="overlay-body"><p>${id==='intro'?'No intro messages will be sent to these 27 buyers.':'Your decision will be saved in the audit trail and this item will leave the approval queue.'}</p></div><div class="overlay-footer row">${button('Cancel','overlay-close')}${actButton(id==='intro'?'Reject batch':'Confirm decline','approval-reject-confirm',id,'danger')}</div>`);return true;}
 if(action==='approval-reject-confirm'){resolveApproval(id,'rejected',ctx);return true;}
 if(action==='finch-embroidery'){d.embroidery=el.value;ctx.updateQuote({embroidery:el.value});return true;}
 if(action==='finch-date'){d.delivery=el.value;ctx.updateQuote({delivery:el.value});return true;}
 if(action==='glow-choice'){d.glowChoice=el.value;ctx.rerender();return true;}
 if(action==='intro-recipient'){d.introExpanded=true;const selected=selectedRecipients(ctx.state).map(b=>b.id);ctx.update({introSelection:el.checked?[...new Set([...selected,id])]:selected.filter(x=>x!==id)});return true;}
 if(action==='intro-select-all'||action==='intro-clear'){d.introExpanded=true;ctx.update({introSelection:action==='intro-clear'?[]:INTRO_RECIPIENTS.map(b=>b.id)});return true;}
 if(action==='intro-cancel-schedule'){ctx.state.scheduledIntro.status='Cancelled';ctx.state.extraActivity=ctx.state.extraActivity.map(e=>e.cat==='messages'&&e.status==='Scheduled'&&/intro/i.test(e.title)?{...e,status:'Cancelled',detail:'Scheduled introductions cancelled by you'}:e);ctx.update({pending:[...new Set(['intro',...ctx.state.pending])],resolved:{...ctx.state.resolved,intro:'cancelled'}});ctx.log(logEntry('Scheduled introductions cancelled','Introduction batch','messages','No introductions sent. Recipients are available for review.',undefined,{status:'Cancelled'}));ctx.rerender();ctx.toast('Schedule cancelled · batch returned to review');return true;}
 if(action==='approval-reply'){d.replyBuyer=id;const name=APPROVALS[id]?.title||BUYERS.find(b=>b.id===id)?.name||'Buyer';ctx.modal(`<div class="overlay-head"><div><h2>Reply to ${esc(name)}</h2><p class="muted">The agent pauses this conversation while you handle it.</p></div>${button('×','overlay-close','ghost','aria-label="Close reply composer"')}</div><div class="overlay-body"><label class="field"><span>Your message</span><textarea rows="5" data-action="reply-message" placeholder="Write your reply…"></textarea></label></div><div class="overlay-footer row">${button('Cancel','overlay-close')}${actButton('Send demo reply','reply-send',id,'primary',ctx.state.paused||!connected(ctx.state,'whatsapp')?'disabled':'')}</div>`);return true;}
 if(action==='reply-message'){d.replyMessage=el.value;return true;}
 if(action==='reply-send'){if(ctx.state.paused||!connected(ctx.state,'whatsapp')){ctx.toast('Resume the agent and connect WhatsApp before sending.');return true;}const text=(document.querySelector('[data-action="reply-message"]')?.value||d.replyMessage||'').trim();if(!text){ctx.toast('Write a message before sending.');return true;}d.replies ||= {};d.replies[id]=[...(d.replies[id]||[]),text];ctx.log(logEntry('Manual reply sent',APPROVALS[id]?.title||BUYERS.find(b=>b.id===id)?.name||'Buyer','messages',text,undefined,{by:'Sent by Neha',why:'You took over this conversation.'}));ctx.update({manualReplies:d.replies,buyerOverrides:{...(ctx.state.buyerOverrides||{}),[id]:{...(ctx.state.buyerOverrides?.[id]||{}),id,status:'Conversation handled by you',tone:'neutral',last:'Just now',updatedAt:new Date().toISOString()}}});ctx.closeOverlay();ctx.toast('Demo reply sent · the agent is quiet for this conversation');return true;}
 if(action==='activity-category'){d.activityCat=id;ctx.rerender();return true;}
 if(action==='activity-who'){d.activityWho=id;ctx.rerender();return true;}
 if(action==='activity-clear'){d.activityCat='all';d.activityWho='all';ctx.rerender();return true;}
 if(action==='activity-open'){const e=events(ctx).find(e=>e.id===id);if(e)ctx.drawer(activityDrawer(e));return true;}
 if(action==='activity-export'){const rows=[['Date','Time','Action','Buyer','Amount','Status','Who','Why'],...events(ctx).filter(e=>(d.activityCat==='all'||e.cat===d.activityCat)&&(d.activityWho==='all'||(d.activityWho==='approved'?e.manual:!e.manual))).map(e=>[e.day==='Yesterday'?'2026-10-11':'2026-10-12',e.time||'',e.title,e.buyer,e.amount||'',e.status,e.by||'',e.why||''])];const csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='razorpay-agent-activity.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);ctx.toast(`Exported ${rows.length-1} actions to CSV`);return true;}
 if(action==='buyers-search'){d.buyerSearch=el.value;ctx.rerender();return true;}
 if(action==='buyers-type'){d.buyerType=el.value;ctx.rerender();return true;}
 if(action==='buyers-group'){d.buyerGroup=id;ctx.rerender();return true;}
 if(action==='buyers-clear'){d.buyerSearch='';d.buyerType='all';d.buyerGroup='all';ctx.rerender();return true;}
 if(action==='buyer-open'){openBuyer(id,ctx);return true;}
 if(action==='buyer-review'){d.approval=id;ctx.closeOverlay();ctx.nav('approvals');return true;}
 if(action.startsWith('buyer-label-')){const label=action.replace('buyer-label-',''),b=BUYERS.find(b=>b.id===id);if(b){const showingBuyer=d.openBuyer===id&&globalThis.document?.querySelector('.drawer-panel .buyer-details');ctx.label(id,label,b.name);if(showingBuyer)openBuyer(id,ctx);else if(label==='exclude')ctx.closeOverlay();}return true;}
 if(action==='buyer-exclude-confirm'){ctx.modal(`<div class="overlay-head"><h2>Exclude ${esc(BUYERS.find(b=>b.id===id)?.name||'this buyer')}?</h2></div><div class="overlay-body"><p>The agent will stop all outreach to this buyer. Their orders and audit trail stay available.</p></div><div class="overlay-footer row">${button('Cancel','overlay-close')}${actButton('Exclude buyer','buyer-label-exclude',id,'danger')}</div>`);return true;}
 if(action==='buyer-resume'){const b=BUYERS.find(b=>b.id===id);ctx.update({buyerOverrides:{...(ctx.state.buyerOverrides||{}),[id]:{...(ctx.state.buyerOverrides?.[id]||{}),status:'Outreach active · within your rules',tone:'info'}}});ctx.log(logEntry('Buyer outreach resumed',b?.name||'Buyer','guardrails','Outreach follows consent and quiet-hour rules'));ctx.toast('Outreach resumed');openBuyer(id,ctx);return true;}
 if(action==='settings-jump'){document.getElementById('settings-'+id)?.scrollIntoView({behavior:'smooth',block:'start'});return true;}
 if(action==='settings-mode'){if(id==='auto'&&!autoAvailable(ctx.state))return true;const c=d.settingsDraft||config(ctx);persistSettingsDraft(ctx,{mode:id,autonomy:id==='review'?Object.fromEntries(AUTONOMY.map(([k])=>[k,c.autonomy[k]==='never'?'never':'ask'])):Object.fromEntries(AUTONOMY.map(([k,,v])=>[k,c.autonomy[k]==='never'?'never':v]))});return true;}
 if(action==='settings-autonomy'){const c=d.settingsDraft||config(ctx);if((c.mode==='review'||AUTONOMY.find(r=>r[0]===id)?.[3])&&el.dataset.value==='auto')return true;persistSettingsDraft(ctx,{autonomy:{...c.autonomy,[id]:el.dataset.value}});return true;}
 if(action==='settings-input'){const key=el.dataset.key,c=d.settingsDraft||config(ctx);if(key.startsWith('tier-')){const tiers=[...c.tiers];tiers[Number(key.slice(5))]=Number(el.value);persistSettingsDraft(ctx,{tiers});}else persistSettingsDraft(ctx,{[key]:el.type==='number'?Number(el.value):el.value});return true;}
 if(action==='settings-confidence'){persistSettingsDraft(ctx,{confidence:Number(el.value)});return true;}
 if(action==='settings-language'){const c=d.settingsDraft||config(ctx);persistSettingsDraft(ctx,{languages:c.languages.includes(id)?c.languages.filter(l=>l!==id):[...c.languages,id]});return true;}
 if(action==='settings-toggle'){const c=d.settingsDraft||config(ctx);persistSettingsDraft(ctx,{[id]:!c[id]});return true;}
 if(action==='settings-discard'){delete d.settingsDraft;ctx.rerender();ctx.toast('Unsaved changes discarded');return true;}
 if(action==='settings-save'){const c=d.settingsDraft;if(!c)return true;if(c.mode==='auto'&&!autoAvailable(ctx.state)){ctx.toast('Automatic mode unlocks after 14 days of review-first.');return true;}const error=validateConfig(c);if(error){ctx.toast(error);return true;}delete d.settingsDraft;const {connectors,...savedRules}=c;ctx.saveConfig(savedRules);ctx.log(logEntry('Agent rules updated','B2B Customer Agent','guardrails',`Quote limit ${money(c.quoteLimit)} · minimum ${c.moq} pieces · ${c.mode==='auto'?'automatic within rules':'review-first'}`,undefined,{why:'You saved new pricing and outreach settings.'}));ctx.toast('Rules saved · they apply to new actions');return true;}
 if(action==='connector-manage'){connectorManage(id,ctx);return true;}
 if(action==='connector-reconnect'||action==='connector-disconnect'){const c=config(ctx),status=action==='connector-disconnect'?'Disconnected':'Connected';ctx.connect(id,status);ctx.closeOverlay();ctx.rerender();ctx.toast(`${CONNECTORS.find(c=>c[0]===id)?.[1]||'Connector'} ${status.toLowerCase()} in demo`);return true;}
 if(action==='settings-pause'){if(ctx.state.paused){ctx.update({paused:false});ctx.log(logEntry('Agent resumed','All buyers','guardrails','Messages, calls and quotes resumed within your rules'));ctx.toast('Agent resumed');}else ctx.modal(`<div class="overlay-head"><h2>Pause B2B Customer Agent?</h2></div><div class="overlay-body"><p>Messages, calls and quotes stop immediately. Pending approvals and buyer data remain available.</p></div><div class="overlay-footer row">${button('Cancel','overlay-close')}${button('Pause agent','settings-pause-confirm','primary')}</div>`);return true;}
 if(action==='settings-pause-confirm'){ctx.update({paused:true});ctx.log(logEntry('Agent paused','All buyers','guardrails','Messages, calls and quotes stopped. Nothing deleted.'));ctx.closeOverlay();ctx.toast('Agent paused · no actions are going out');return true;}
 if(action==='settings-uninstall'){ctx.modal(`<div class="overlay-head"><h2>Uninstall B2B Customer Agent?</h2></div><div class="overlay-body"><p>This removes the agent’s synthetic connections and returns you to Agent Studio. Your activity history is preserved.</p></div><div class="overlay-footer row">${button('Cancel','overlay-close')}${button('Uninstall demo agent','settings-uninstall-confirm','danger')}</div>`);return true;}
 if(action==='settings-uninstall-confirm'){ctx.log(logEntry('Agent uninstalled','B2B Customer Agent','guardrails','All synthetic agent access removed'));ctx.update({installed:false,paused:false});ctx.closeOverlay();ctx.nav('studio');ctx.toast('Demo agent uninstalled · activity history preserved');return true;}
 return false;
}
